import 'package:flutter/material.dart';
import '../../../customer_orders/data/models/customer_order_model.dart';
class RecentOrdersCard extends StatelessWidget { const RecentOrdersCard({required this.orders, super.key}); final List<CustomerOrderModel> orders; @override Widget build(BuildContext context) => Card(child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('Recent Customer Orders', style: Theme.of(context).textTheme.titleMedium), const SizedBox(height: 8), if (orders.isEmpty) const Text('No orders yet') else ...orders.take(5).map((o) => ListTile(contentPadding: EdgeInsets.zero, title: Text(o.customerName), subtitle: Text('${o.branchName ?? ''} · ${o.orderType}'), trailing: Column(crossAxisAlignment: CrossAxisAlignment.end, children: [Text('\$${o.totalAmount.toStringAsFixed(2)}'), Text(o.status)])))]))); }
